>     let nameAt = 0;
>     let patternAt = 0;
>     let star = -1;
>     let starName = 0;
>     while (nameAt < name.length) {
>         const ch = pattern[patternAt];
>         if (ch !== undefined && (ch === '?' || ch === name[nameAt])) {
>             nameAt += 1;
>             patternAt += 1;
>             continue;
